  var RULE_AGE = 59.5, MIN_YEARS = 5;   // IRC 72(t)(4): 5 years or age 59 1/2, whichever is later
  var SAFE_HARBOR_RATE = 5;             // Notice 2022-6 s. 3.02(c): up to the greater of 5% or 120% of the federal mid-term rate
  // ----------------------------------------------------------------------------------------------------

  function singleLE(a) { return SINGLE[Math.min(Math.max(a, 0), 120)]; }
  function uniformLE(a) { return UNIFORM[Math.min(Math.max(a, UNIFORM_FROM), 120) - UNIFORM_FROM]; }
  function jointLE(o, b) {
    var row = JOINT[Math.min(o, JOINT_FROM + JOINT.length - 1) - JOINT_FROM];
    var k = Math.min(Math.max(b, 0), 120) * 2;
    return parseInt(row.substr(k, 2), 36) / 10;
  }
  function lifeExpectancy(table, o, b) {
    if (table === 'joint') return jointLE(o, b);
    if (table === 'uniform') return uniformLE(o);
    return singleLE(o);
  }
  // Survival probabilities kp_x for k = 0..(121 - x).
  function survival(x) {
    var p = [1];
    for (var a = x; a <= 120; a++) p.push(p[p.length - 1] * (1 - MORTALITY[a]));
    return p;
  }
  // Present value of $1 a year paid at the end of each year while alive (single or last survivor).
  function annuityFactor(x, y, i, joint) {
    var px = survival(x), py = joint ? survival(y) : [], n = Math.max(px.length, py.length), s = 0;
    for (var k = 1; k < n; k++) {
      var a = k < px.length ? px[k] : 0, b = joint && k < py.length ? py[k] : 0;
      s += (joint ? a + b - a * b : a) / Math.pow(1 + i, k);
    }
    return s;
  }
  function amortFactor(n, i) { return i === 0 ? n : (1 - Math.pow(1 + i, -n)) / i; }

  // p: balance, age, benAge, table ('single' | 'uniform' | 'joint'), rate, growth (decimals), method.
  function compute(p) {
    var le = lifeExpectancy(p.table, p.age, p.benAge);
    var af = amortFactor(le, p.rate);
    var ann = annuityFactor(p.age, p.benAge, p.rate, p.table === 'joint');
    var res = { le: le, amortFactor: af, annFactor: ann, rmd: p.balance / le, amort: p.balance / af,
                annuity: p.balance / ann };
    var years = Math.max(MIN_YEARS, Math.ceil(RULE_AGE - p.age));
    var bal = p.balance, rows = [], total = 0, depleted = false;
    for (var y = 0; y < years; y++) {
      var a = p.age + y, start = bal, pay;
      if (p.method === 'rmd') pay = start / lifeExpectancy(p.table, a, p.benAge + y);
      else pay = p.method === 'amort' ? res.amort : res.annuity;
      var grown = start * (1 + p.growth);
      if (pay > grown) { pay = grown; depleted = true; }
      bal = grown - pay;
      total += pay;
      rows.push({ year: y + 1, age: a, start: start, pay: pay, end: bal });
    }
    res.years = years; res.rows = rows; res.total = total; res.endBalance = bal; res.depleted = depleted;
    res.endAge = Math.max(p.age + MIN_YEARS, RULE_AGE);
    return res;
