  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }
  function ageText(a) { return a % 1 ? Math.floor(a) + '½' : String(a); }
  var NAMES = { rmd: 'RMD method', amort: 'Fixed amortization', annuity: 'Fixed annuitization' };
  var TABLE_NAMES = { single: 'Single Life', uniform: 'Uniform Lifetime', joint: 'Joint and Last Survivor' };

  function update() {
    var balance = num('stBalance'), age = num('stAge'), benAge = num('stBenAge'), rate = num('stRate'),
        growth = num('stGrowth'), table = document.getElementById('stTable').value,
        method = document.getElementById('stMethod').value;
    var joint = table === 'joint';
    document.getElementById('stBenWrap').hidden = !joint;
    var error = document.getElementById('stError');
    var bad = isNaN(balance) || isNaN(age) || isNaN(rate) || isNaN(growth) || balance <= 0 ||
              age !== Math.round(age) || age < 18 || age > 59 || rate < 0 || rate > 15 || growth < -50 || growth > 30 ||
              (joint && (isNaN(benAge) || benAge !== Math.round(benAge) || benAge < 0 || benAge > 120));
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a balance above $0, a whole-number age from 18 to 59, an interest rate from 0 to 15%, ' +
