    set('stRmd', fmt(r.rmd)); set('stAmort', fmt(r.amort)); set('stAnnuity', fmt(r.annuity));
    set('stRmdMonthly', fmt(r.rmd / 12) + ' a month');
    set('stAmortMonthly', fmt(r.amort / 12) + ' a month');
    set('stAnnuityMonthly', fmt(r.annuity / 12) + ' a month');
    ['Rmd', 'Amort', 'Annuity'].forEach(function (k) {
      var card = document.getElementById('st' + k + 'Card');
      card.className = 'stat-card' + (k.toLowerCase() === method ? ' stat-card-highlight' : '');
    });
    set('stLe', r.le.toFixed(1) + ' years (' + TABLE_NAMES[table] + ')');
    set('stAmortFactor', r.amortFactor.toFixed(4));
    set('stAnnFactor', r.annFactor.toFixed(4) + (joint ? ' (joint lives)' : ' (your life)'));
    set('stEnd', 'Age ' + ageText(r.endAge) + ' – ' + r.years + ' annual payments');
    set('stTotal', fmt(r.total));
    set('stEndBal', fmt(r.endBalance));
    var rateNote = document.getElementById('stRateNote');
    rateNote.hidden = !(rate > SAFE_HARBOR_RATE);
    if (rate > SAFE_HARBOR_RATE) {
      set('stRateNote', 'A rate above ' + SAFE_HARBOR_RATE + '% is allowed only if 120% of the federal mid-term rate ' +
          'for either of the two months before your first payment is at least that high.');
    }
    var dep = document.getElementById('stDepleted');
    dep.hidden = !r.depleted;
    if (r.depleted) set('stDepleted', 'At this return the ' + NAMES[method].toLowerCase() +
        ' payment empties the account before the payments can stop.');
    set('stScheduleIntro', NAMES[method] + ' payments until age ' + ageText(r.endAge) +
        ', with the balance growing ' + growth + '% a year. Change the method above to see another schedule.');
    var body = document.getElementById('stSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.year, row.age, fmt(row.start), fmt(row.pay), fmt(row.end)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('stForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
